    ("MCP_OAUTH_ENABLED", "Tools / code-exec / cron / approvals", "OFF (`False`)", "Inject OAuth `Authorization` headers into SSE/HTTP/streamable MCP server connections that declare an `auth: {provider: \"generic_oauth2\", ...}` block (`MCPServerConfig.auth`) — mints/refreshes the token via a persisted (`FileTokenStore`, Fernet-encrypted), lazily-built `OAuthMana…", "advanced"),
    ("MCP_SELF_INSTALL_ENABLED", "Tools / code-exec / cron / approvals", "OFF (`False`)", "Register the agent-callable `mcp_install` action (install a vetted catalog MCP server at runtime). Forged/autonomous turns always refused; approval is Deny-by-default unless `APPROVAL_PROVIDER` is set. NOT in the `POLYROB_LOCAL` safe group.", "advanced"),
    ("MCP_INSTALL_CATALOG_FILE", "Tools / code-exec / cron / approvals", "unset", "Path to a REVIEWED JSON file of extra installable catalog entries (`{\"<id>\": {description, transport, url/command, trust}}`), merged over the builtins (file wins on id clash). The real operator seam for extending the install catalog.", "advanced"),
    ("MCP_INSTALL_ALLOWLIST", "Tools / code-exec / cron / approvals", "unset", "Comma list of extra ids admitted to the install allowlist. An id WITHOUT a catalog entry still has nothing to install — prefer `MCP_INSTALL_CATALOG_FILE`.", "advanced"),
