    ("DOCKER_HOST", "Tools / code-exec / cron / approvals", "unset (docker default `unix:///var/run/docker.sock`)", "Read only to locate the docker daemon socket the `docker` sandbox backend would use: when it names a `unix://` socket that is absent or unreachable, `run_code`/`run_tests` refuse ONCE with the remedy (proposal 053) instead of retrying a dead daemon; a TCP `DOCKER_HOST` is not pr…", "advanced"),
    ("CODE_EXEC_MAX_TIMEOUT_SEC", "Tools / code-exec / cron / approvals", "`30` (dev mode, unset: follows `SHELL_MAX_TIMEOUT_SEC`=600)", "Hard cap on a code-exec run. An explicit value always wins; unset under the docker backend's dev mode (posture ≥1) the cap follows `SHELL_MAX_TIMEOUT_SEC` so `run_code` and `shell_run` share ONE foreground ceiling. Unset, `coding.run_tests` also gets that ceiling on every backen…", "advanced"),
    ("CODE_EXEC_MAX_OUTPUT_BYTES", "Tools / code-exec / cron / approvals", "`100000`", "Code-exec output byte cap.", "advanced"),
    ("CODE_EXEC_DOCKER_IMAGE", "Tools / code-exec / cron / approvals", "`python:3.12-slim`", "Container image for the `docker` code-exec backend (explicit value wins over `CODE_EXEC_DEV_IMAGE` in every mode).", "advanced"),
    ("CODE_EXEC_DEV_IMAGE", "Tools / code-exec / cron / approvals", "`nikolaik/python-nodejs:python3.11-nodejs20`", "Image for the posture≥1 persistent DEV container when `CODE_EXEC_DOCKER_IMAGE` is unset — python+node so npm/npx toolchains work (014 B1).", "advanced"),
    ("CODE_EXEC_NETWORK", "Tools / code-exec / cron / approvals", "`none`", "Docker container network policy: `none` / `egress` (→ docker `bridge`) / `host` / `proxy` (073 W8: the persistent session sandbox sits on an `--internal` network behind ONE allowlist proxy sidecar — package registries only, see `CODE_EXEC_EGRESS_ALLOW`; a setup failure refuses,…", "advanced"),
    ("CODE_EXEC_EGRESS_ALLOW", "Tools / code-exec / cron / approvals", "registries", "Hosts the `proxy` network may reach. Unset = package registries (PyPI, npm, GitHub, crates, Go proxy, RubyGems, Maven Central, Debian). `+a.com,b.org` appends; any other value replaces. `*.x.com` / `.x.com` match subdomains.", "advanced"),
    ("CODE_EXEC_EGRESS_PORTS", "Tools / code-exec / cron / approvals", "`443,80`", "Extra ports (comma list) the `proxy` network allows on top of 443 and 80.", "advanced"),
    ("CODE_EXEC_CONTAINER_MEMORY_MB", "Tools / code-exec / cron / approvals", "`1024`", "Docker container memory cap (MB); also sets `--memory-swap` equal (no swap headroom).", "advanced"),
    ("CODE_EXEC_CONTAINER_CPUS", "Tools / code-exec / cron / approvals", "`1.0`", "Docker container CPU cap (`--cpus`).", "advanced"),
    ("CODE_EXEC_PIDS_LIMIT", "Tools / code-exec / cron / approvals", "`256`", "Docker container PID cap (`--pids-limit`).", "advanced"),
    ("CODE_EXEC_SHM_SIZE_MB", "Tools / code-exec / cron / approvals", "`1024`", "Docker container `/dev/shm` size (MB, `--shm-size`). Docker's own default is 64MB regardless of `--memory` — too small for a real headless-Chromium render (Puppeteer/Playwright/Remotion mmap frame buffers there); a bare `chromium --headless` page fetch doesn't hit it, only an ac…", "advanced"),
    ("CODE_EXEC_DOCKER_USER", "Tools / code-exec / cron / approvals", "unset → invoking uid:gid, or `65534:65534` (nobody:nogroup) when the host process itself runs as root", "Explicit override for the docker backend's `--user`.", "advanced"),
    ("CODE_EXEC_DOCKER_PERSISTENT", "Tools / code-exec / cron / approvals", "OFF (**ON at `AGENT_COMPUTE_POSTURE>=1`**)", "Opt-in: ONE persistent per-session `docker` container (`docker exec` per call) instead of a fresh ephemeral container per `run_code` call, so pip installs/cwd survive across calls within a session. Defaults ON at posture≥1 (sandbox-dev installs must persist); explicit value wins.", "advanced"),
    ("CODE_EXEC_DOCKER_BINARY", "Tools / code-exec / cron / approvals", "`docker`", "The container CLI the docker backend shells out to — e.g. `podman` (no daemon socket probe then). A value starting with `-` is refused.", "advanced"),
    ("CODE_EXEC_DOCKER_REUSE_ACROSS_RESTART", "Tools / code-exec / cron / approvals", "OFF", "A session's persistent container is labelled with its config hash; after an agent restart the session re-attaches to its running container instead of creating a new one. Off while `CODE_EXEC_TOOL_CALLS` is on or under `CODE_EXEC_NETWORK=proxy`.", "advanced"),
    ("CODE_EXEC_TOOL_CALLS", "Tools / code-exec / cron / approvals", "OFF", "`run_code(tools=True)`: a Python script calls an allowlist of agent tools (web fetch/search, knowledge, memory/session search, workspace files, foreground `shell`) over a per-run Unix-socket RPC; every call re-enters the controller, so every gate and approval applies. Max 50 cal…", "advanced"),
    ("CODE_EXEC_PUBLISH_PORTS", "Tools / code-exec / cron / approvals", "`8000,5000,8080,3000`", "Container ports a dev (posture≥1) persistent sandbox publishes to host loopback (`-p 127.0.0.1::<port>`, docker-assigned host ports) so the agent can HTTP-test a server it started. Non-dev/ephemeral runs publish nothing.", "advanced"),
    ("CODE_EXEC_SSH_HOST", "Tools / code-exec / cron / approvals", "unset (required for `CODE_EXEC_BACKEND=ssh`)", "Remote host the `ssh` code-exec backend runs `run_code` on over the system `ssh` binary. `setup()` fails loudly if unset when `ssh` is selected; refused if the value begins with `-` (option-injection guard).", "advanced"),
    ("CODE_EXEC_SSH_USER", "Tools / code-exec / cron / approvals", "unset (omit `user@` — SSH client/`~/.ssh/config` default applies)", "SSH login user for the `ssh` code-exec backend. Refused if the value begins with `-`.", "advanced"),
    ("CODE_EXEC_SSH_PORT", "Tools / code-exec / cron / approvals", "`22`", "SSH port for the `ssh` code-exec backend.", "advanced"),
    ("CODE_EXEC_SSH_KEY", "Tools / code-exec / cron / approvals", "unset", "Identity file (`-i`) for the `ssh` code-exec backend. Never logged (only host/port/exit-code are logged; the full argv, which carries this path, is not).", "advanced"),
    ("CODE_EXEC_SSH_KNOWN_HOSTS", "Tools / code-exec / cron / approvals", "unset (`StrictHostKeyChecking=accept-new`, trust on first use)", "Path (`~` expanded) to a pinned `known_hosts` file for the `ssh` code-exec backend and the `ssh` shell session. Set → `StrictHostKeyChecking=yes` + `UserKnownHostsFile=<path>`: only a host key already in that file is trusted, so a first-contact man-in-the-middle is refused. A mi…", "advanced"),
    ("CODE_EXEC_SSH_SANDBOXED", "Tools / code-exec / cron / approvals", "OFF (`False`)", "Operator ATTESTATION that the `CODE_EXEC_SSH_HOST` remote is hardened/disposable, flipping the `ssh` backend's reported `capabilities[\"sandbox\"]` True. By default it is honestly `False` — a generic remote host is a different trust domain where agent code runs with the SSH user's…", "advanced"),
    ("SHELL_TOOLS_ENABLED", "Tools / code-exec / cron / approvals", "OFF (**ON at `AGENT_COMPUTE_POSTURE>=1`**)", "Register the persistent `shell` + `process` tools (run inside the session's sandbox container — or on the host at posture 3, see `SHELL_BACKEND`; cwd/env persist; background job manager with list/poll/wait/log/kill). Every action is additionally `compute_posture_allows(ctx,1)`-g…", "public"),
    ("SHELL_MAX_TIMEOUT_SEC", "Tools / code-exec / cron / approvals", "`600`", "ONE foreground ceiling for the agent's build commands: `shell_run` clamps its `timeout` to it (180 when the agent omits `timeout`; a request ABOVE it runs as a background job instead — 073 W3) and the docker backend's dev-mode `run_code` cap follows it when `CODE_EXEC_MAX_TIMEOU…", "advanced"),
    ("SHELL_BACKEND", "Tools / code-exec / cron / approvals", "`auto`", "Where `shell`/`process` run (073 W1/W6). `auto` = the host when THIS turn passes `host_shell_refusal` (posture 3 + `POLYROB_LOCAL` + no in-process signing key + the owner's terminal turn), else the session sandbox. `docker` = never the host. `host` = the host or an honest refusa…", "advanced"),
    ("SHELL_APPROVAL_MODE", "Tools / code-exec / cron / approvals", "`per_command`", "When `shell_run` is approval-gated (posture ≥ 2, or listed in `APPROVAL_REQUIRED_TOOLS`): `per_command` = only a command the guard classes DANGEROUS waits for the owner (073 W2, `core/security/command_guard.py`); a safe one runs. `every` = every gated call waits (the pre-073 beh…", "advanced"),
    ("SHELL_MAX_OUTPUT_CHARS", "Tools / code-exec / cron / approvals", "`50000`", "Characters of one `shell_run` result the model reads (073 W3): over it, 40 % head + 60 % tail around one notice, and the full (redacted) text saved under the session `logs/shell/` with its path in the notice. ANSI codes are stripped and credential shapes redacted on every result…", "advanced"),
    ("SHELL_DENY", "Tools / code-exec / cron / approvals", "empty", "Comma list of shell command globs (whole command line, `fnmatch`) that are refused before any approval, on every backend. UNIONed with the owner's `shell.deny` pref (an approval prompt's [n]ever writes the exact command there).", "advanced"),
    ("SHELL_ALLOW", "Tools / code-exec / cron / approvals", "empty", "Comma list of shell command globs that skip the owner approval wait. Never lifts the guard's floor. UNIONed with the owner's `shell.allow` pref (an approval prompt's [a]lways queues the exact command there for `/pending` review).", "advanced"),
    ("SHELL_HOST_SUDO", "Tools / code-exec / cron / approvals", "`refuse`", "`sudo` on the HOST shell (073 W5). `refuse` = never. `prompt` = for a foreground host command at the terminal seat, the owner types the password on the tty once per command; it reaches `sudo -S` on stdin only and is never cached, logged or put in env. `doas`/`su`/`pkexec` stay r…", "advanced"),
    ("SHELL_HOST_FORWARD_AGENT", "Tools / code-exec / cron / approvals", "OFF", "Pass the owner's `SSH_AUTH_SOCK` into host shell commands so `git`/`ssh` can use the ssh-agent (it signs; no key leaves it).", "advanced"),
    ("SHELL_HOST_INIT_FILES", "Tools / code-exec / cron / approvals", "empty", "Comma list of files (`~` expanded) every host shell command sources first, quietly (e.g. `~/.bashrc` for nvm/pyenv PATH). ⚠️ Whatever they export becomes visible to the agent's commands — a secret exported there (an API key, a token) bypasses the child-env name scrub. Keep secre…", "advanced"),
    ("APP_SERVICE_ENABLED", "Tools / code-exec / cron / approvals", "OFF (ON under effective `AGENT_BUILDER_MODE=ship`)", "032: register the `app_service` tool (`deploy`/`stop`/`list_apps`/`logs`) and arm the owner-owned supervisor unit. Never in default `tool_ids`; a stream manifest or the owner grants it per goal. The agent only writes registry rows — `polyrob-apps.service` (`polyrob apps supervis…", "public"),
    ("APP_SERVICE_ALLOW_PUBLIC", "Tools / code-exec / cron / approvals", "OFF (ON under effective `AGENT_BUILDER_MODE=ship`)", "Render the public nginx stanza for a live app (`https://<slug>.<APP_SERVICE_BASE_DOMAIN>`). OFF ⇒ apps run on loopback only and `app_list` says so. NOT flipped by `POLYROB_LOCAL`.", "advanced"),
    ("APP_SERVICE_BASE_DOMAIN", "Tools / code-exec / cron / approvals", "unset", "The wildcard base, e.g. `apps.example.com` (one `*.apps.example.com` certificate). Required for a public URL; without it `ship` mode clamps to `build`.", "advanced"),
    ("APP_SERVICE_MAX_LIVE", "Tools / code-exec / cron / approvals", "`3`", "Apps per tenant that may hold an address (approved/deploying/live/paused).", "advanced"),
    ("APP_SERVICE_DAILY_MAX", "Tools / code-exec / cron / approvals", "`10`", "Deploy requests per tenant per rolling 24 h.", "advanced"),
    ("APP_SERVICE_MIN_INTERVAL_SEC", "Tools / code-exec / cron / approvals", "`120`", "Minimum seconds between deploy requests of ONE slug.", "advanced"),
    ("APP_SERVICE_MEMORY_MB", "Tools / code-exec / cron / approvals", "`512`", "Per-app container memory ceiling (memory == memory-swap).", "advanced"),
    ("APP_SERVICE_CPUS", "Tools / code-exec / cron / approvals", "`0.5`", "Per-app CPU ceiling.", "advanced"),
    ("APP_SERVICE_PIDS", "Tools / code-exec / cron / approvals", "`256`", "Per-app pid ceiling.", "advanced"),
    ("APP_SERVICE_SNAPSHOT_MAX_MB", "Tools / code-exec / cron / approvals", "`500`", "Cap on the tested-tree snapshot an app runs from (symlinks, `.git`, caches and credential files are never copied).", "advanced"),
    ("APP_SERVICE_EGRESS_DEFAULT", "Tools / code-exec / cron / approvals", "`none`", "Egress when the verb omits it: `none` (deny all but replies) \\", "advanced"),
    ("APP_SERVICE_PORT_RANGE", "Tools / code-exec / cron / approvals", "`18000-18099`", "Loopback host ports the supervisor allocates from (the agent never chooses a port).", "advanced"),
