    ("APP_SERVICE_HEALTH_TIMEOUT_SEC", "Tools / code-exec / cron / approvals", "`90`", "Time to the first healthy `health_path` response before a deploy is `failed`.", "advanced"),
    ("APP_SERVICE_IMAGE", "Tools / code-exec / cron / approvals", "`CODE_EXEC_DEV_IMAGE` else `polyrob-dev:latest`", "Base image an app container runs in.", "advanced"),
    ("APP_SERVICE_RETAIN_DAYS", "Tools / code-exec / cron / approvals", "`7`", "Days a stopped/failed app's snapshot is kept before pruning.", "advanced"),
